import { test, expect } from './fixtures';

test('edits an input cell in the new sheet UI and confirms the value is kept', async ({ page }) => {
  await page.goto('/');

  // Wait for the new sheet/cell UI to render.
  const inputCells = page.locator('inputcell');
  await expect(inputCells.first()).toBeVisible({ timeout: 15000 });

  // The sheet is wrapped by a sheet-name provider and contains custom cells.
  await expect(page.locator('sheetnameprovider').first()).toBeVisible();
  await expect(page.locator('customcell').first()).toBeVisible();

  // Primary interaction: edit the first input cell.
  const firstInputCell = inputCells.first();
  const firstCellInput = firstInputCell.locator('input, textarea').first();
  await expect(firstCellInput).toBeEditable();

  await firstCellInput.click();
  await firstCellInput.fill('1234.56');
  await firstCellInput.press('Enter');

  // The typed value is reflected back in the cell.
  await expect(firstCellInput).toHaveValue('1234.56');

  // Trigger the sheet's action button and verify the edit is persisted.
  const actionButton = page.getByRole('button').first();
  await expect(actionButton).toBeVisible();
  await actionButton.click();

  await expect(firstCellInput).toHaveValue('1234.56');
});

import { test, expect } from './fixtures';

test('desktop smoke: app loads and cart route is reachable', async ({ page }) => {
  await page.goto('/#/');
  await page.waitForLoadState('domcontentloaded');

  await expect(page).toHaveURL(/#\/$/);
  await expect(page.locator('body')).toBeVisible();
  await expect(page.locator('main, [role="main"], #root, #app').first()).toBeVisible();

  await page.goto('/#/cart');
  await page.waitForLoadState('domcontentloaded');

  await expect(page).toHaveURL(/#\/cart$/);
  await expect(page.locator('body')).toBeVisible();
  await expect(page.locator('main, [role="main"], #root, #app').first()).toBeVisible();
});

import type { Page } from './fixtures';

import { test, expect } from './fixtures';
import { ConfigurationPage } from './page-models/configuration-page';
import { MobileNavigation } from './page-models/mobile-navigation';

test.describe('Mobile transaction amount sign toggle', () => {
  let page: Page;
  let navigation: MobileNavigation;
  let configurationPage: ConfigurationPage;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    navigation = new MobileNavigation(page);
    configurationPage = new ConfigurationPage(page);

    await page.setViewportSize({
      width: 350,
      height: 600,
    });
    await page.goto('/');
    await configurationPage.createTestFile();
  });

  test.afterEach(async () => {
    await page?.close();
  });

  test('toggles the amount sign using the ± button on the mobile transaction entry screen', async () => {
    const accountsPage = await navigation.goToAccountsPage();
    await accountsPage.waitFor();

    const accountPage = await accountsPage.openNthAccount(0);
    await accountPage.waitFor();

    const transactionEntryPage = await accountPage.addNewTransaction();
    await transactionEntryPage.waitFor();

    await transactionEntryPage.enterAmount(100);
    await expect(transactionEntryPage.amount).toContainText('100');
    await expect(transactionEntryPage.amount).not.toContainText('-');

    const signToggle = page.getByText('±', { exact: true });
    await expect(signToggle).toBeVisible();
    await expect(page).toMatchThemeScreenshots();

    await signToggle.click();
    await expect(transactionEntryPage.amount).toContainText('-');
    await expect(transactionEntryPage.amount).toContainText('100');
    await expect(page).toMatchThemeScreenshots();

    await signToggle.click();
    await expect(transactionEntryPage.amount).not.toContainText('-');
    await expect(transactionEntryPage.amount).toContainText('100');
  });
});

import { test, expect } from './fixtures';

test.describe('actual_desktop smoke', () => {
  test('loads app, opens cart, and returns home', async ({ page }) => {
    // 1. Load the app shell
    await page.goto('/#/');
    await expect(page).toHaveURL(/#\/?$/);
    await expect(page.locator('body')).toBeVisible();

    // 2. Navigate to the cart using the in-app navigation
    const cartLink = page
      .locator('a[href*="/cart"], [data-testid="cart-link"], [aria-label*="cart" i]')
      .first();
    await expect(cartLink).toBeVisible();
    await cartLink.click();
    await expect(page).toHaveURL(/#\/cart/);

    // 3. Cart view should render without crashing
    await expect(page.locator('main, [role="main"], #root, #app').first()).toBeVisible();

    // 4. Return home and confirm the app still renders
    await page.goto('/#/');
    await expect(page).toHaveURL(/#\/?$/);
    await expect(page.locator('body')).toBeVisible();
  });
});
